CASES=[
('בג"ץ 2918/93 עיריית קריית גת נ\' מדינת ישראל','עובדות: הממשלה קבעה מפת ערי פיתוח מכוח הסמכות השיורית, אף שחוק ערי ואזורי פיתוח (1988) הסדיר את הנושא.','הלכה: גולדברג קבע שמשקיים דין היוצר הסדר, נסוגה מפניו סמכות הממשלה, וס\' 32 מפורש בצמצום; אך כשהחוק אינו מיושם בפועל ייתכן מסלול אחר. דורנר: "כל דין" כולל גם הלכה פסוקה וזכויות יסוד. חשיבות למבחן: גבולות הסמכות השיורית.'),
('בג"ץ 5128/94 פדרמן נ\' שר המשטרה','עובדות: ישראל שלחה שוטרים להדרכת כוח משטרה בהאיטי, בלי הסדר בחקיקה.','הלכה: שמגר קבע שבריק משפטי הסמכות השיורית כוללת קשרים וסיוע בינלאומי. העתירה נדחתה. חשיבות למבחן: הפעלה כדין של סעיף 32.'),
('בג"ץ 5062/97 איגוד שמאי הביטוח נ\' מדינת ישראל','עובדות: במקום להכריז על אסון טבע לפי החוק, ניתנה לחקלאים סובסידיה מכוח הסמכות השיורית.','הלכה: העתירה נדחתה כתיאורטית. השופט אור הוסיף באגב שרק אחרי שהממשלה בחנה ענייני וסביר את הפעלת החוק והחליטה שלא להכריז, אפשר לפנות לסמכות השיורית. חשיבות למבחן: צמצום של קריית גת.'),
('בג"ץ 757/84 איגוד העיתונים היומיים נ\' רשות השידור','עובדות: רשות השידור ביקשה לשדר תשדירי שירות, שקופיות חסות ופרסומות.','הלכה: תשדירי שירות בסמכות מפורשת; חסות – סמכות עזר במידה המתקבלת על הדעת; פרסומות אסורות כי הן סותרות את המהות הציבורית של הרשות. חשיבות למבחן: הזיקה הנדרשת בין סמכות עזר לסמכות הראשית.'),
('ע"א 9657/03 מגן דוד אדום נ\' הממונה על השכר','עובדות: הוועד המנהל של מד"א החליט לשלם שכר ליו"ר שהתנדב עד אז.','הלכה: השופט ג\'ובראן הבחין בין מישור פנימי, שבו סמכויות העזר רחבות, למישור חיצוני שבו הן מצומצמות. תשלום שכר ליו"ר חורג מהניהול הפנימי ונדרשת הסמכה מפורשת. אפשר לגבות מחיר, אך לא אגרה ומס. חשיבות למבחן: גבולות סמכות העזר.'),
('רע"א 2558/16 פלונית נ\' קצין התגמולים','עובדות: קצין התגמולים שלח חוקר פרטי לצלם נכה, והפחית את נכותה על סמך הצילומים.','הלכה: מגבלה יסודית על הכרה בסמכות עזר היא שאין היא משמשת לפגיעה בזכויות יסוד; מעקב פוגע בפרטיות, ולכן אין סמכות. חשיבות למבחן: סמכות עזר אינה מקור לפגיעה בזכויות.'),
('בג"ץ 171/69 פילצר נ\' שר האוצר; רע"פ 1057/99 יוחייב','עובדות: הפקעה לפי הפקודה המחמירה ולא לפי החוק הידידותי יותר; טיפול במשתמט בדרך הקשוחה.','הלכה: בפילצר (לנדוי) – כששני חיקוקים שווי דרגה הרשות רשאית לבחור. ביוחייב – הבחירה כפופה למידתיות: להעדיף את הפוגעת פחות, אלא אם יש שיקולים לשנייה. חשיבות למבחן: ריבוי מקורות סמכות.'),
('ע"פ 74/58 היועץ המשפטי לממשלה נ\' הורנשטיין','עובדות: חוק עזר הסמיך את ראש העירייה לקבוע מקומות חנייה בתשלום, מדחן או סדרן, ותעריפים.','הלכה: אגרנט קבע שסמכות מעין-חקיקה מחייבת נורמה שמשנה את המשפט ושהיא כללית. קביעת מקום מוסדר ותעריף היא מעין-חקיקה שאין להעביר ("שליח אינו עושה שליח"); הבחירה בין מדחן לסדרן היא ביצוע. חשיבות למבחן: מבחן מעין-חקיקה.'),
('בג"ץ 3/58 ברמן נ\' שר הפנים; בש"א 136/90 מדינת ישראל נ\' סלוק','עובדות: העברת שכונה מעיר לעיר; סירוב לרישיון חוקר פרטי.','הלכה: בברמן קבע זילברג שגם החלטה שפוגעת באדם מחייבת שמיעה, ושמעין-שיפוט הוא הכרעה על סמך ממצאים במחלוקת בין שני צדדים. בסלוק: המבחן העיקרי הוא קיומו של סכסוך בין שני צדדים. חשיבות למבחן: מבחן מעין-שפיטה.'),
('בג"ץ 295/65 אופנהיימר נ\' שרי הפנים והבריאות','עובדות: השרים היו "רשאים" להתקין תקנות לחוק המפגעים ולא עשו זאת במשך ארבע שנים.','הלכה: בכל סמכות רשות יש רכיב חובה (להפעיל בזמן סביר) ורכיב רשות (תוכן). השאלה פרשנית לפי מהות הפעולה. חשיבות למבחן: סיווג סמכויות לחובה ורשות.'),
]
